class LoginVM {
  user = '';
  constructor() { makeObservable(this, { user: observable, canSubmit: computed, submit: action }); }
  get canSubmit() { return this.user.trim().length > 0; }
  submit() { api.login(this.user); }
}
const vm = new LoginVM();
autorun(() => render(vm.user, vm.canSubmit));   // reaction = the binder
